using Microsoft.Data.SqlClient;
using Dapper;

public class SqlVectorCatalogService
{
    private readonly string _connectionString;

    public SqlVectorCatalogService(string connectionString)
    {
        _connectionString = connectionString;
    }

    public async Task<List<ProductCatalogDto>> SearchProductsAsync(
        float[] queryVector,
        string categoryFilter,
        int topCount = 5,
        CancellationToken ct = default)
    {
        await using var connection = new SqlConnection(_connectionString);
        var vectorJson = JsonSerializer.Serialize(queryVector);

        // Uses T-SQL VECTOR_DISTANCE function with cosine metric
        var sql = """
            SELECT TOP (@topCount) 
                p.Id, p.Title, p.Price, p.Category,
                VECTOR_DISTANCE('cosine', p.EmbeddingVector, JSON_ARRAY_TO_VECTOR(@vectorJson)) AS Distance
            FROM Products p
            WHERE p.Category = @categoryFilter
            ORDER BY Distance ASC
        """;

        var results = await connection.QueryAsync<ProductCatalogDto>(
            sql,
            new { topCount, vectorJson, categoryFilter });

        return results.ToList();
    }
}

public record ProductCatalogDto(int Id, string Title, decimal Price, string Category, double Distance);
